namespace {
std::string s8(const std::u8string& u) { return std::string(u.begin(), u.end()); }
constexpr double kTolHz = 5.0;
constexpr int kMaxBands = 500, kMaxChannels = 200000, kMaxExplicit = 5000;
constexpr size_t kMaxFile = 4u << 20;

const char* const kServices[] = {"tv", "fm", "dab", "am", "air", "pmr", "marine", "ham", "ism", "other"};

std::string lower(std::string s) { for (char& c : s) c = (char)std::tolower((unsigned char)c); return s; }
std::string trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && std::isspace((unsigned char)s[a])) a++;
    while (b > a && std::isspace((unsigned char)s[b - 1])) b--;
    return s.substr(a, b - a);
}
std::string mhzText(double hz) { char b[48]; std::snprintf(b, sizeof b, "%.6g MHz", hz / 1e6); return b; }
std::string num(double v) {   // the shortest text that reads back as the same double
    char b[40];
    std::snprintf(b, sizeof b, "%.15g", v);
    if (std::strtod(b, nullptr) != v) std::snprintf(b, sizeof b, "%.17g", v);
    return b;
}
double centre0(const Band& b) { return b.firstCentreHz > 0 ? b.firstCentreHz : (b.bandwidthHz > 0 ? b.startHz + b.bandwidthHz / 2 : b.startHz); }

// The strict number reading of the CSV cells: the whole cell must be a finite number.
bool readNum(const std::string& s, double& v) {
    const std::string t = trim(s);
    if (t.empty()) return false;
    char* e = nullptr;
    v = std::strtod(t.c_str(), &e);
    return e && *e == 0 && std::isfinite(v);
}

// ------------------------------------------------------------------ files
bool readAll(const std::string& path, std::string& s, std::string& err) {
    std::error_code ec;
    const auto sz = std::filesystem::file_size(u8file(path), ec);
    if (ec) { err = "cannot open " + path; return false; }
    if (sz > kMaxFile) { err = "the file is larger than 4 MB"; return false; }
    std::ifstream f(u8file(path), std::ios::binary);
    if (!f) { err = "cannot open " + path; return false; }
    std::stringstream ss;
    ss << f.rdbuf();
    s = ss.str();
    return true;
}
bool writeAtomic(const std::string& path, const std::string& data, std::string& err) {
    const std::filesystem::path p = u8file(path), tmp = u8file(path + ".tmp");
    std::error_code ec;
    if (p.has_parent_path()) std::filesystem::create_directories(p.parent_path(), ec);
    {
        std::ofstream f(tmp, std::ios::binary | std::ios::trunc);
        if (!f) { err = "cannot write " + path; return false; }
        f.write(data.data(), (std::streamsize)data.size());
        f.flush();
        if (!f) { err = "writing " + path + " failed"; std::filesystem::remove(tmp, ec); return false; }
    }
    std::filesystem::rename(tmp, p, ec);   // replaces an existing file; a crash never leaves half a plan
    if (ec) { err = "cannot replace " + path + ": " + ec.message(); std::filesystem::remove(tmp, ec); return false; }
    return true;
}

// ------------------------------------------------------------------ JSON
using mj::Value;

bool numField(const Value& o, const char* key, double& dst, std::string& err, const std::string& ctx) {
    const Value* v = o.get(key);
    if (!v || v->kind == Value::Null) return true;
    if (v->kind != Value::Num || !std::isfinite(v->num)) { err = ctx + ": \"" + key + "\" must be a number"; return false; }
    dst = v->num;
    return true;
}
bool strField(const Value& o, const char* key, std::string& dst, std::string& err, const std::string& ctx) {
    const Value* v = o.get(key);
    if (!v || v->kind == Value::Null) return true;
    if (v->kind != Value::Str) { err = ctx + ": \"" + key + "\" must be text"; return false; }
    dst = v->str;
    return true;
}
bool strList(const Value& o, const char* key, std::vector<std::string>& dst, std::string& err, const std::string& ctx) {
    const Value* v = o.get(key);
    if (!v || v->kind == Value::Null) return true;
    if (v->kind == Value::Str) { dst.push_back(v->str); return true; }
    if (v->kind != Value::Arr) { err = ctx + ": \"" + key + "\" must be a list of texts"; return false; }
    for (const Value& e : v->arr) {
        if (e.kind != Value::Str) { err = ctx + ": \"" + key + "\" must be a list of texts"; return false; }
        dst.push_back(e.str);
    }
    return true;
}
bool bandFromJson(const Value& o, Band& b, std::string& err, const std::string& ctx) {
    if (o.kind != Value::Obj) { err = ctx + " must be an object"; return false; }
    double first = -1;
    if (!strField(o, "name", b.name, err, ctx) || !strField(o, "service", b.service, err, ctx) || !numField(o, "start_hz", b.startHz, err, ctx) ||
        !numField(o, "end_hz", b.endHz, err, ctx) || !numField(o, "step_hz", b.stepHz, err, ctx) || !numField(o, "bandwidth_hz", b.bandwidthHz, err, ctx) ||
        !numField(o, "first_channel", first, err, ctx) || !numField(o, "first_centre_hz", b.firstCentreHz, err, ctx) || !strList(o, "modes", b.modes, err, ctx) ||
        !strField(o, "note", b.note, err, ctx) || !strField(o, "source", b.source, err, ctx))
        return false;
    if (std::fabs(first) > 1e9 || first != std::floor(first)) { err = ctx + ": \"first_channel\" must be a whole number"; return false; }
    b.firstChannel = (int)first;
    if (const Value* ch = o.get("channels"); ch && ch->kind != Value::Null) {
        if (ch->kind != Value::Arr) { err = ctx + ": \"channels\" must be a list"; return false; }
        for (const Value& c : ch->arr) {
            NamedChannel n;
            if (c.kind != Value::Obj) { err = ctx + ": each channel must be an object with \"label\" and \"centre_hz\""; return false; }
            if (!strField(c, "label", n.label, err, ctx + " channel") || !numField(c, "centre_hz", n.centreHz, err, ctx + " channel")) return false;
            if (!c.get("centre_hz")) { err = ctx + ": a channel has no \"centre_hz\""; return false; }
            b.channels.push_back(n);
            if ((int)b.channels.size() > kMaxExplicit) { err = ctx + ": more than 5000 explicit channels"; return false; }
        }
    }
    return true;
}
bool planHeaderFromJson(const Value& o, Plan& p, std::string& err) {
    double itu = 0;
    if (!strField(o, "name", p.name, err, "plan") || !strField(o, "region", p.region, err, "plan") || !strField(o, "source", p.source, err, "plan") ||
        !strField(o, "note", p.note, err, "plan") || !numField(o, "itu_region", itu, err, "plan") || !strList(o, "countries", p.countries, err, "plan"))
        return false;
    p.ituRegion = (int)itu;
    if (const Value* c = o.get("confidence"); c && c->kind == Value::Str) p.verified = c->str != "check";
    if (const Value* c = o.get("verified"); c && c->kind == Value::Bool) p.verified = c->b;
    return true;
}

// ------------------------------------------------------------------ CSV
// Cells may be quoted ("" is a quote); a quoted cell may hold commas and line breaks. Lines starting with # outside a cell are comments / plan fields.
struct CsvRow { std::vector<std::string> cells; int line = 0; };
bool csvRows(const std::string& t, std::vector<CsvRow>& rows, std::vector<std::pair<std::string, std::string>>& meta, std::string& err) {
    size_t i = 0;
    int line = 1;
    if (t.compare(0, 3, "\xEF\xBB\xBF") == 0) i = 3;
    while (i < t.size()) {
        if (t[i] == '\r' || t[i] == '\n') { if (t[i] == '\n') line++; i++; continue; }
        if (t[i] == '#') {
            size_t e = t.find('\n', i);
            if (e == std::string::npos) e = t.size();
            std::string l = trim(t.substr(i + 1, e - i - 1));
            const size_t c = l.find(':');
            if (c != std::string::npos) meta.emplace_back(lower(trim(l.substr(0, c))), trim(l.substr(c + 1)));
            i = e;
            continue;
        }
        CsvRow r;
        r.line = line;
        std::string cell;
        bool inQ = false, done = false;
        while (i < t.size() && !done) {
            const char c = t[i];
            if (inQ) {
                if (c == '"') { if (i + 1 < t.size() && t[i + 1] == '"') { cell += '"'; i += 2; } else { inQ = false; i++; } }
                else { if (c == '\n') line++; cell += c; i++; }
            } else if (c == '"' && cell.empty()) { inQ = true; i++; }
            else if (c == ',') { r.cells.push_back(cell); cell.clear(); i++; }
            else if (c == '\n' || c == '\r') { done = true; }
            else { cell += c; i++; }
        }
        if (inQ) { err = "line " + std::to_string(r.line) + ": a quoted cell is not closed"; return false; }
        r.cells.push_back(cell);
        rows.push_back(std::move(r));
        if ((int)rows.size() > kMaxBands + 1) { err = "more than 500 bands"; return false; }
    }
    return true;
}
std::string csvCell(const std::string& s) {
    if (s.find_first_of(",\"\r\n") == std::string::npos) return s;
    std::string o = "\"";
    for (char c : s) { if (c == '"') o += '"'; o += c; }
    return o + "\"";
}
std::string join(const std::vector<std::string>& v, const char* sep) {
    std::string o;
    for (size_t i = 0; i < v.size(); i++) { if (i) o += sep; o += v[i]; }
    return o;
}
std::vector<std::string> split(const std::string& s, char sep) {
    std::vector<std::string> o;
    std::string cur;
    for (char c : s) { if (c == sep) { o.push_back(trim(cur)); cur.clear(); } else cur += c; }
    o.push_back(trim(cur));
    o.erase(std::remove_if(o.begin(), o.end(), [](const std::string& x) { return x.empty(); }), o.end());
    return o;
}

// ------------------------------------------------------------------ built-in plans
void expand(const Value& root, std::vector<Plan>& out) {
    const Value* tm = root.get("templates");
    const Value* pl = root.get("plans");
    if (!pl || pl->kind != Value::Arr) return;
    for (const Value& pv : pl->arr) {
        Plan p;
        std::string err;
        if (pv.kind != Value::Obj || !planHeaderFromJson(pv, p, err)) continue;
        if (const Value* id = pv.get("id"); id && id->kind == Value::Str) p.id = id->str;
        p.builtin = true;
        auto add = [&](const Value& bands, const std::string& src) {
            if (bands.kind != Value::Arr) return;
            for (const Value& bv : bands.arr) {
                Band b;
                if (!bandFromJson(bv, b, err, "band")) continue;
                if (b.source.empty()) b.source = src;
                p.bands.push_back(std::move(b));
            }
        };
        if (const Value* use = pv.get("use"); use && use->kind == Value::Arr && tm)
            for (const Value& u : use->arr) if (u.kind == Value::Str)
                if (const Value* t = tm->get(u.str)) {
                    const Value* s = t->get("source");
                    if (const Value* bs = t->get("bands")) add(*bs, s && s->kind == Value::Str ? s->str : std::string());
                }
        if (const Value* bs = pv.get("bands")) add(*bs, p.source);
        if (!validate(p, err)) continue;
        out.push_back(std::move(p));
    }
}
} // namespace

// ------------------------------------------------------------------ Band
int Band::count() const {
    if (!channels.empty()) return (int)channels.size();
    if (stepHz <= 0) return 0;
    const double c0 = centre0(*this), hi = endHz + kTolHz - bandwidthHz / 2;
    if (c0 > hi) return 0;
    const double n = std::floor((hi - c0) / stepHz + 1e-9) + 1;
    return n > kMaxChannels ? kMaxChannels : (int)n;
}
std::vector<Channel> Band::list(size_t cap) const {
    std::vector<Channel> o;
    const int n = count();
    for (int k = 0; k < n && o.size() < cap; k++) {
        Channel c;
        if (!channels.empty()) { c.label = channels[(size_t)k].label; c.centreHz = channels[(size_t)k].centreHz; }
        else {
            c.centreHz = centre0(*this) + k * stepHz;
            if (firstChannel >= 0) { c.number = firstChannel + k; c.label = std::to_string(c.number); }
        }
        o.push_back(std::move(c));
    }
    return o;
}
bool Band::channelCentre(int number, double& hz) const {
    if (!channels.empty() || stepHz <= 0 || firstChannel < 0) return false;
    const long k = (long)number - firstChannel;
    if (k < 0 || k >= count()) return false;
    hz = centre0(*this) + (double)k * stepHz;
    return true;
}
bool Band::channelAt(double hz, Channel& out, double tolHz) const {
    const int n = count();
    if (n <= 0 || !std::isfinite(hz)) return false;
    if (!channels.empty()) {
        const double tol = tolHz >= 0 ? tolHz : std::max(bandwidthHz / 2, 1000.0);
        int best = -1;
        double bd = 1e30;
        for (int k = 0; k < n; k++) { const double d = std::fabs(channels[(size_t)k].centreHz - hz); if (d < bd) { bd = d; best = k; } }
        if (best < 0 || bd > tol) return false;
        out.number = -1; out.label = channels[(size_t)best].label; out.centreHz = channels[(size_t)best].centreHz;
        return true;
    }
    const double tol = tolHz >= 0 ? tolHz : stepHz / 2 + 1e-6;
    const double kf = std::round((hz - centre0(*this)) / stepHz);
    if (kf < 0 || kf >= n) return false;
    const int k = (int)kf;
    const double c = centre0(*this) + k * stepHz;
    if (std::fabs(c - hz) > tol) return false;
    out.centreHz = c;
    out.number = firstChannel >= 0 ? firstChannel + k : -1;
    out.label = out.number >= 0 ? std::to_string(out.number) : std::string();
    return true;
}

const Band* Plan::firstBand(const std::string& service) const {
    for (const Band& b : bands) if (b.service == service) return &b;
    return nullptr;
}
std::vector<const Band*> Plan::bandsFor(const std::string& service, const std::string& mode) const {
    std::vector<const Band*> o;
    for (const Band& b : bands) {
        if (b.service != service) continue;
        if (!mode.empty() && std::find(b.modes.begin(), b.modes.end(), mode) == b.modes.end()) continue;
        o.push_back(&b);
    }
    return o;
}

// ------------------------------------------------------------------ validation
bool validate(Plan& p, std::string& err) {
    p.name = trim(p.name);
    if (p.name.empty()) { err = "the plan has no name"; return false; }
    if (p.name.size() > 120) { err = "the plan name is longer than 120 characters"; return false; }
    if (p.bands.empty()) { err = "the plan has no bands"; return false; }
    if ((int)p.bands.size() > kMaxBands) { err = "the plan has more than 500 bands"; return false; }
    if (p.ituRegion < 0 || p.ituRegion > 3) { err = "itu_region must be 1, 2 or 3 (or left out)"; return false; }
    for (std::string& c : p.countries) {
        c = trim(c);
        for (char& ch : c) ch = (char)std::toupper((unsigned char)ch);
        if (c.size() < 2 || c.size() > 3 || !std::all_of(c.begin(), c.end(), [](char ch) { return ch >= 'A' && ch <= 'Z'; })) { err = "country \"" + c + "\" is not a 2 or 3 letter code (DE, GB, ...)"; return false; }
    }
    int idx = 0;
    for (Band& b : p.bands) {
        idx++;
        const std::string ctx = "band " + std::to_string(idx) + " (\"" + b.name + "\")";
        b.name = trim(b.name);
        if (b.name.empty()) { err = "band " + std::to_string(idx) + " has no name"; return false; }
        if (b.name.size() > 120) { err = ctx + ": the name is longer than 120 characters"; return false; }
        b.service = lower(trim(b.service));
        if (b.service.empty()) b.service = "other";
        if (std::find_if(std::begin(kServices), std::end(kServices), [&](const char* s) { return b.service == s; }) == std::end(kServices)) {
            err = ctx + ": unknown service \"" + b.service + "\" (use " + [] { std::string s; for (const char* x : kServices) { if (!s.empty()) s += ", "; s += x; } return s; }() + ")";
            return false;
        }
        if (!std::isfinite(b.startHz) || !std::isfinite(b.endHz) || b.startHz <= 0) { err = ctx + ": start_hz must be a positive number of Hz"; return false; }
        if (b.endHz <= b.startHz) { err = ctx + ": end_hz (" + mhzText(b.endHz) + ") must be above start_hz (" + mhzText(b.startHz) + ")"; return false; }
        if (b.endHz > 3e11) { err = ctx + ": end_hz is above 300 GHz; the values are in Hz"; return false; }
        if (!std::isfinite(b.stepHz) || b.stepHz < 0) { err = ctx + ": step_hz must not be negative"; return false; }
        if (!std::isfinite(b.bandwidthHz) || b.bandwidthHz < 0 || b.bandwidthHz > b.endHz - b.startHz + kTolHz) { err = ctx + ": bandwidth_hz must be between 0 and the width of the band"; return false; }
        if (b.firstChannel < -1 || b.firstChannel > 1000000) { err = ctx + ": first_channel must be between 0 and 1000000"; return false; }
        if (!b.channels.empty()) {
            if (b.stepHz > 0 || b.firstChannel >= 0 || b.firstCentreHz > 0) { err = ctx + ": give either a list of channels or step_hz with first_channel / first_centre_hz, not both"; return false; }
            if ((int)b.channels.size() > kMaxExplicit) { err = ctx + ": more than 5000 channels"; return false; }
            for (NamedChannel& c : b.channels) {
                if (!std::isfinite(c.centreHz) || c.centreHz < b.startHz - b.bandwidthHz / 2 - kTolHz || c.centreHz > b.endHz + b.bandwidthHz / 2 + kTolHz) {
                    err = ctx + ": channel \"" + c.label + "\" at " + mhzText(c.centreHz) + " lies outside the band"; return false;
                }
                if (c.label.empty()) c.label = mhzText(c.centreHz);
                if (c.label.size() > 40) { err = ctx + ": a channel label is longer than 40 characters"; return false; }
            }
        } else if (b.stepHz > 0) {
            if (!std::isfinite(b.firstCentreHz) || b.firstCentreHz < 0) { err = ctx + ": first_centre_hz must be a positive number of Hz"; return false; }
            const double c0 = centre0(b);
            if (c0 < b.startHz + b.bandwidthHz / 2 - kTolHz || c0 > b.endHz - b.bandwidthHz / 2 + kTolHz) {
                err = ctx + ": the first channel centre (" + mhzText(c0) + ") lies outside the band " + mhzText(b.startHz) + " to " + mhzText(b.endHz); return false;
            }
            const double n = std::floor((b.endHz + kTolHz - b.bandwidthHz / 2 - c0) / b.stepHz + 1e-9) + 1;
            if (n > kMaxChannels) { err = ctx + ": the raster would have " + std::to_string((long long)n) + " channels (the limit is 200000); check step_hz (in Hz)"; return false; }
        } else if (b.firstChannel >= 0 || b.firstCentreHz > 0) {
            err = ctx + ": first_channel and first_centre_hz need step_hz"; return false;
        }
        if (b.modes.size() > 32) { err = ctx + ": more than 32 modes"; return false; }
        for (std::string& m : b.modes) { m = trim(m); if (m.size() > 60) { err = ctx + ": a mode name is longer than 60 characters"; return false; } }
        b.modes.erase(std::remove_if(b.modes.begin(), b.modes.end(), [](const std::string& m) { return m.empty(); }), b.modes.end());
    }
    return true;
}

// ------------------------------------------------------------------ readers
bool parseJson(const std::string& text, Plan& out, std::string& err) {
    out = Plan();
    if (text.size() > kMaxFile) { err = "the file is larger than 4 MB"; return false; }
    Value root;
    std::string perr;
    const size_t bom = text.compare(0, 3, "\xEF\xBB\xBF") == 0 ? 3 : 0;
    if (!mj::parse(text.substr(bom), root, perr)) { err = "not valid JSON: " + perr; return false; }
    if (root.kind != Value::Obj) { err = "a band plan is a JSON object with \"name\" and \"bands\""; return false; }
    if (!planHeaderFromJson(root, out, err)) return false;
    const Value* bands = root.get("bands");
    if (!bands || bands->kind != Value::Arr) { err = "the plan has no \"bands\" list"; return false; }
    if ((int)bands->arr.size() > kMaxBands) { err = "the plan has more than 500 bands"; return false; }
    int i = 0;
    for (const Value& bv : bands->arr) {
        Band b;
        i++;
        if (!bandFromJson(bv, b, err, "band " + std::to_string(i))) return false;
        out.bands.push_back(std::move(b));
    }
    return validate(out, err);
}

bool parseCsv(const std::string& text, Plan& out, std::string& err) {
    out = Plan();
    if (text.size() > kMaxFile) { err = "the file is larger than 4 MB"; return false; }
    std::vector<CsvRow> rows;
    std::vector<std::pair<std::string, std::string>> meta;
    if (!csvRows(text, rows, meta, err)) return false;
    for (const auto& m : meta) {
        if (m.first == "name") out.name = m.second;
        else if (m.first == "region") out.region = m.second;
        else if (m.first == "source") out.source = m.second;
        else if (m.first == "note") out.note = m.second;
        else if (m.first == "country" || m.first == "countries") { std::string v = m.second; for (char& c : v) if (c == ';' || c == ' ') c = ','; out.countries = split(v, ','); }
        else if (m.first == "itu_region") { double v = 0; if (!readNum(m.second, v)) { err = "# itu_region must be 1, 2 or 3"; return false; } out.ituRegion = (int)v; }
        else if (m.first == "verified") out.verified = lower(m.second) != "no" && lower(m.second) != "false";
    }
    if (rows.empty()) { err = "the file has no header row"; return false; }
    // columns by name; start / end / step / bandwidth / first_centre may be given in Hz, kHz or MHz (start_mhz ...)
    const std::vector<std::pair<std::string, std::pair<std::string, double>>> alias = {
        {"band", {"name", 1}}, {"name", {"name", 1}}, {"service", {"service", 1}}, {"type", {"service", 1}},
        {"start_hz", {"start", 1}}, {"start_khz", {"start", 1e3}}, {"start_mhz", {"start", 1e6}}, {"start", {"start", 1}},
        {"end_hz", {"end", 1}}, {"end_khz", {"end", 1e3}}, {"end_mhz", {"end", 1e6}}, {"end", {"end", 1}}, {"stop_hz", {"end", 1}}, {"stop_mhz", {"end", 1e6}},
        {"step_hz", {"step", 1}}, {"step_khz", {"step", 1e3}}, {"step_mhz", {"step", 1e6}}, {"step", {"step", 1}}, {"raster_hz", {"step", 1}}, {"raster_khz", {"step", 1e3}},
        {"bandwidth_hz", {"bw", 1}}, {"bandwidth_khz", {"bw", 1e3}}, {"bandwidth_mhz", {"bw", 1e6}}, {"bw_hz", {"bw", 1}}, {"bw_khz", {"bw", 1e3}}, {"bw_mhz", {"bw", 1e6}},
        {"first_channel", {"first", 1}}, {"first_centre_hz", {"centre", 1}}, {"first_centre_khz", {"centre", 1e3}}, {"first_centre_mhz", {"centre", 1e6}},
        {"first_center_hz", {"centre", 1}}, {"first_center_mhz", {"centre", 1e6}}, {"modes", {"modes", 1}}, {"note", {"note", 1}}, {"source", {"bsource", 1}}, {"channels", {"channels", 1}}};
    std::map<std::string, std::pair<size_t, double>> col;
    const CsvRow& hdr = rows[0];
    for (size_t i = 0; i < hdr.cells.size(); i++) {
        const std::string h = lower(trim(hdr.cells[i]));
        for (const auto& a : alias) if (a.first == h) { col[a.second.first] = {i, a.second.second}; break; }
    }
    for (const char* need : {"name", "start", "end"})
        if (!col.count(need)) { err = std::string("line ") + std::to_string(hdr.line) + ": the header row has no \"" + (!strcmp(need, "name") ? "band" : !strcmp(need, "start") ? "start_hz" : "end_hz") + "\" column (found: " + join(hdr.cells, ", ") + ")"; return false; }
    for (size_t r = 1; r < rows.size(); r++) {
        const CsvRow& row = rows[r];
        const std::string ctx = "line " + std::to_string(row.line);
        auto cell = [&](const char* k) -> std::string { auto it = col.find(k); return it != col.end() && it->second.first < row.cells.size() ? trim(row.cells[it->second.first]) : std::string(); };
        auto numCell = [&](const char* k, double& dst) -> bool {
            const std::string s = cell(k);
            if (s.empty()) return true;
            double v;
            if (!readNum(s, v)) { err = ctx + ": \"" + s + "\" is not a number (column " + k + ")"; return false; }
            dst = v * col[k].second;
            return true;
        };
        if (row.cells.size() == 1 && trim(row.cells[0]).empty()) continue;
        Band b;
        b.name = cell("name");
        if (!cell("service").empty()) b.service = cell("service");
        double first = -1;
        if (!numCell("start", b.startHz) || !numCell("end", b.endHz) || !numCell("step", b.stepHz) || !numCell("bw", b.bandwidthHz) || !numCell("centre", b.firstCentreHz)) return false;
        if (!cell("first").empty()) {
            if (!readNum(cell("first"), first) || first != std::floor(first) || std::fabs(first) > 1e9) { err = ctx + ": first_channel must be a whole number"; return false; }
            b.firstChannel = (int)first;
        }
        b.modes = split(cell("modes"), ';');
        b.note = cell("note");
        b.source = cell("bsource");
        for (const std::string& c : split(cell("channels"), ';')) {   // label=centre_hz;label=centre_hz
            const size_t eq = c.find('=');
            NamedChannel n;
            if (eq == std::string::npos || !readNum(c.substr(eq + 1), n.centreHz)) { err = ctx + ": channels must read label=centre_hz;label=centre_hz (got \"" + c + "\")"; return false; }
            n.label = trim(c.substr(0, eq));
            b.channels.push_back(n);
            if ((int)b.channels.size() > kMaxExplicit) { err = ctx + ": more than 5000 channels"; return false; }
        }
        if (b.name.empty() && b.startHz == 0 && b.endHz == 0) continue;
        if (b.name.empty()) { err = ctx + ": the band has no name"; return false; }
        if (cell("start").empty() || cell("end").empty()) { err = ctx + ": band \"" + b.name + "\" needs start_hz and end_hz"; return false; }
        out.bands.push_back(std::move(b));
    }
    if (!validate(out, err)) return false;
    return true;
}

// ------------------------------------------------------------------ writers
std::string toJson(const Plan& p) {
    std::string o = "{\n  \"format\": \"onair-bandplan-1\",\n  \"name\": " + mj::quote(p.name) + ",\n  \"region\": " + mj::quote(p.region) + ",\n";
    o += "  \"itu_region\": " + std::to_string(p.ituRegion) + ",\n  \"countries\": [";
    for (size_t i = 0; i < p.countries.size(); i++) o += (i ? ", " : "") + mj::quote(p.countries[i]);
    o += "],\n  \"source\": " + mj::quote(p.source) + ",\n  \"note\": " + mj::quote(p.note) + ",\n  \"verified\": " + (p.verified ? "true" : "false") + ",\n  \"bands\": [\n";
    for (size_t i = 0; i < p.bands.size(); i++) {
        const Band& b = p.bands[i];
        o += "    {\"name\": " + mj::quote(b.name) + ", \"service\": " + mj::quote(b.service) + ", \"start_hz\": " + num(b.startHz) + ", \"end_hz\": " + num(b.endHz);
        if (b.stepHz > 0) o += ", \"step_hz\": " + num(b.stepHz);
        if (b.bandwidthHz > 0) o += ", \"bandwidth_hz\": " + num(b.bandwidthHz);
        if (b.firstChannel >= 0) o += ", \"first_channel\": " + std::to_string(b.firstChannel);
        if (b.firstCentreHz > 0) o += ", \"first_centre_hz\": " + num(b.firstCentreHz);
        if (!b.modes.empty()) { o += ", \"modes\": ["; for (size_t k = 0; k < b.modes.size(); k++) o += (k ? ", " : "") + mj::quote(b.modes[k]); o += "]"; }
        if (!b.channels.empty()) {
            o += ", \"channels\": [";
            for (size_t k = 0; k < b.channels.size(); k++) o += (k ? ", " : "") + std::string("{\"label\": ") + mj::quote(b.channels[k].label) + ", \"centre_hz\": " + num(b.channels[k].centreHz) + "}";
            o += "]";
        }
        if (!b.note.empty()) o += ", \"note\": " + mj::quote(b.note);
        if (!b.source.empty()) o += ", \"source\": " + mj::quote(b.source);
        o += i + 1 < p.bands.size() ? "},\n" : "}\n";
    }
    return o + "  ]\n}\n";
}

std::string toCsv(const Plan& p) {
    std::string o = "# name: " + p.name + "\n# region: " + p.region + "\n# itu_region: " + std::to_string(p.ituRegion) + "\n# countries: " + join(p.countries, ",") + "\n";
    if (!p.source.empty()) o += "# source: " + p.source + "\n";
    if (!p.note.empty()) o += "# note: " + p.note + "\n";
    if (!p.verified) o += "# verified: no\n";
    for (char& c : o) if (c == '\r') c = ' ';
    o += "band,service,start_hz,end_hz,step_hz,bandwidth_hz,first_channel,first_centre_hz,modes,channels,note,source\n";
    for (const Band& b : p.bands) {
        std::string ch;
        for (size_t k = 0; k < b.channels.size(); k++) ch += (k ? ";" : "") + b.channels[k].label + "=" + num(b.channels[k].centreHz);
        o += csvCell(b.name) + "," + b.service + "," + num(b.startHz) + "," + num(b.endHz) + "," + (b.stepHz > 0 ? num(b.stepHz) : "") + "," + (b.bandwidthHz > 0 ? num(b.bandwidthHz) : "") + "," +
             (b.firstChannel >= 0 ? std::to_string(b.firstChannel) : "") + "," + (b.firstCentreHz > 0 ? num(b.firstCentreHz) : "") + "," + csvCell(join(b.modes, ";")) + "," + csvCell(ch) + "," + csvCell(b.note) + "," + csvCell(b.source) + "\n";
    }
    return o;
}

std::string slug(const std::string& name) {
    std::string o;
    bool dash = false;
    for (unsigned char c : name) {
        if (std::isalnum(c) && c < 128) { if (dash && !o.empty()) o += '-'; o += (char)std::tolower(c); dash = false; }
        else dash = true;
        if (o.size() >= 40) break;
    }
    return o.empty() ? "plan" : o;
}

// ------------------------------------------------------------------ the built-in plans and the registry
const char* builtinBandPlanText() { return kBuiltinBandPlans; }
const std::vector<Plan>& builtinPlans() {
    static const std::vector<Plan> plans = [] {
        std::vector<Plan> o;
        Value root;
        std::string err;
        if (mj::parse(kBuiltinBandPlans, root, err)) expand(root, o);
        return o;
    }();
    return plans;
}

Registry::Registry() : plans_(builtinPlans()) {}

void Registry::setUserDir(const std::string& dir) {
    dir_ = dir;
    plans_ = builtinPlans();
    log_.clear();
    std::error_code ec;
    if (dir.empty() || !std::filesystem::is_directory(u8file(dir), ec)) return;
    std::vector<std::filesystem::path> files;
    for (const auto& e : std::filesystem::directory_iterator(u8file(dir), ec))
        if (e.is_regular_file(ec) && e.path().extension() == ".json") files.push_back(e.path());
    std::sort(files.begin(), files.end());
    for (const auto& f : files) {
        std::string text, err;
        Plan p;
        if (!readAll(s8(f.u8string()), text, err) || !parseJson(text, p, err)) { log_.push_back(s8(f.filename().u8string()) + ": " + err); continue; }
        p.id = s8(f.stem().u8string());
        if (p.id.compare(0, 5, "user-") != 0 || find(p.id)) { log_.push_back(s8(f.filename().u8string()) + ": not a user plan file name"); continue; }
        plans_.push_back(std::move(p));
    }
}

const Plan* Registry::find(const std::string& id) const {
    for (const Plan& p : plans_) if (p.id == id) return &p;
    return nullptr;
}

bool Registry::store(Plan& p, std::string& err, bool* replaced) {
    if (replaced) *replaced = false;
    const std::string base = "user-" + slug(p.name);
    std::string id = base;
    int n = 1;
    for (;;) {   // the same name replaces; another plan with the same slug gets -2, -3 ...
        const Plan* e = find(id);
        if (!e) break;
        if (!e->builtin && e->name == p.name) { if (replaced) *replaced = true; break; }
        id = base + "-" + std::to_string(++n);
        if (n > 999) { err = "too many plans with the same name"; return false; }
    }
    p.id = id;
    p.builtin = false;
    if (dir_.empty()) { err = "there is no folder for user plans"; return false; }
    if (!writeAtomic(dir_ + "/" + id + ".json", toJson(p), err)) return false;
    auto it = std::find_if(plans_.begin(), plans_.end(), [&](const Plan& q) { return q.id == id; });
    if (it != plans_.end()) *it = p; else plans_.push_back(p);
    return true;
}

bool Registry::importText(const std::string& text, std::string& id, std::string& err, bool* replaced) {
    Plan p;
    size_t i = text.compare(0, 3, "\xEF\xBB\xBF") == 0 ? 3 : 0;
    while (i < text.size() && std::isspace((unsigned char)text[i])) i++;
    const bool ok = i < text.size() && text[i] == '{' ? parseJson(text, p, err) : parseCsv(text, p, err);
    if (!ok) return false;
    if (!store(p, err, replaced)) return false;
    id = p.id;
    return true;
}

bool Registry::importFile(const std::string& path, std::string& id, std::string& err, bool* replaced) {
    std::string text;
    if (!readAll(path, text, err)) return false;
    return importText(text, id, err, replaced);
}

bool Registry::remove(const std::string& id, std::string& err) {
    auto it = std::find_if(plans_.begin(), plans_.end(), [&](const Plan& q) { return q.id == id; });
    if (it == plans_.end()) { err = "no such band plan"; return false; }
    if (it->builtin) { err = "the built-in plans cannot be deleted"; return false; }
    std::error_code ec;
    std::filesystem::remove(u8file(dir_ + "/" + id + ".json"), ec);
    if (ec) { err = "cannot delete the file: " + ec.message(); return false; }
    plans_.erase(it);
    return true;
}

bool Registry::exportFile(const std::string& id, const std::string& path, bool csv, std::string& err) const {
    const Plan* p = find(id);
    if (!p) { err = "no such band plan"; return false; }
    return writeAtomic(path, csv ? toCsv(*p) : toJson(*p), err);
}

std::string Registry::localeFromEnv() {
    for (const char* k : {"LC_ALL", "LC_MESSAGES", "LANG"}) if (const char* v = std::getenv(k); v && *v) return v;
    return std::string();
}

std::string Registry::defaultFor(const std::string& lang, const std::string& locale) const {
    static const std::pair<const char*, const char*> byLang[] = {{"de", "de"}, {"fr", "fr"}, {"it", "it"}, {"es", "es"}, {"nl", "nl"}, {"pl", "pl"}, {"lt", "lt"},
                                                                {"ja", "jp"}, {"zh", "cn"}, {"pt", "br"}, {"hu", "eu"}};
    std::string full = lower(lang.substr(0, lang.find_first_of(".@")));
    std::replace(full.begin(), full.end(), '_', '-');
    if (full == "pt-pt" && find("eu")) return "eu";   // Portuguese (Portugal): the CEPT plan, not Brazil's
    std::string l = lower(lang.substr(0, lang.find_first_of("-_")));
    for (const auto& e : byLang) if (l == e.first && find(e.second)) return e.second;
    // the region of the system locale: en_GB.UTF-8 -> GB
    const size_t u = locale.find('_');
    if (u != std::string::npos && u + 2 < locale.size() + 0) {
        std::string cc = locale.substr(u + 1, 2);
        for (char& c : cc) c = (char)std::toupper((unsigned char)c);
        for (const Plan& p : plans_) if (p.builtin && std::find(p.countries.begin(), p.countries.end(), cc) != p.countries.end()) return p.id;
    }
    return std::string();
}

